node -e "
const fs = require('fs');
const d = JSON.parse(fs.readFileSync('inputs/previous-feedback.txt','utf8'));
const comm = d.resources.communication;
console.log('before ranks:', comm.before.map(r=>r.rank));
for (const r of comm.before) {
  let sum = 0; const durs=[];
  for (const c of r.collectives) { for (const k of c.kernels) { sum += k.duration_us; durs.push(Math.round(k.duration_us/100)/10); } }
  console.log('rank', r.rank, 'collectives', r.collectives.length, 'nccl_sum_ms', (sum/1000).toFixed(2), 'per-collective ms:', durs.join(', '));
}
console.log('AFTER:');
for (const r of comm.after) {
  let sum = 0; const durs=[];
  for (const c of r.collectives) { for (const k of c.kernels) { sum += k.duration_us; durs.push(Math.round(k.duration_us/100)/10); } }
  console.log('rank', r.rank, 'collectives', r.collectives.length, 'nccl_sum_ms', (sum/1000).toFixed(2), 'per-collective ms:', durs.join(', '));
}
"

